export function searchCountries(query: string, limit = 8): CountryPreset[] {
  const q = query.trim().toLowerCase()
  if (!q) return []

  const scored = COUNTRY_PRESETS.map((c) => {
    const nameLower = c.name.toLowerCase()
    let score = 0
    if (nameLower === q) score = 100
    else if (nameLower.startsWith(q)) score = 80
    else if (c.aliases.some((a) => a === q)) score = 75
    else if (c.aliases.some((a) => a.startsWith(q))) score = 60
    else if (nameLower.includes(q)) score = 40
    else if (c.aliases.some((a) => a.includes(q))) score = 30
    return { c, score }
  }).filter((x) => x.score > 0)

  scored.sort((a, b) => b.score - a.score || a.c.name.localeCompare(b.c.name))
  return scored.slice(0, limit).map((x) => x.c)
}
